const mp3Base64 = "data:audio/mp3;base64,"

const audio = new Audio(mp3Base64);

const sequence = ['ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown', 'Enter'];
let cursor = 0;

document.addEventListener('keydown', (e) => {
  // Check if the pressed key matches the current expected step
  if (e.code === sequence[cursor]) {
    cursor++;
    // If the full sequence is completed
    if (cursor === sequence.length) {
      secretCodeActivate();
      cursor = 0; // Reset for the next time
    }
  } else {
    // Reset or check if the key matches the start of the sequence
    cursor = (e.code === sequence[0]) ? 1 : 0;
  }
});

function secretCodeActivate() {
  if (audio.paused) {
        audio.play().catch(error => console.error("Playback failed:", error));
    } else {
        audio.pause();
    }
}
